<?php
namespace Tests\Feature;
use App\Models\{Student,User,AcademicYear,AttendanceSession,AttendanceLog};
use App\Services\{SemesterTraining,AttendanceLedger};
use Illuminate\Support\Facades\{DB,Schema};
use Illuminate\Database\Schema\Blueprint;
use Laravel\Sanctum\Sanctum;
class SemesterTrainingTest extends ProjectReviewRegressionTest {

 private function student():Student {$u=User::create(['first_name'=>'Test','last_name'=>'Student','email'=>uniqid().'@example.test','student_id'=>uniqid(),'role'=>'student','password'=>'password123','is_active'=>true]);return Student::create(['user_id'=>$u->id,'student_id'=>$u->student_id]);}
 private function log(Student $s,float $hours,int $period=1,string $review='approved'):AttendanceLog {$id=DB::table('classes')->insertGetId(['teacher_id'=>$s->user_id,'name'=>'Test','component_type'=>'cwts','join_code'=>uniqid(),'status'=>'active','academic_year_id'=>$period]);$session=AttendanceSession::create(['class_id'=>$id,'faculty_id'=>$s->user_id,'status'=>'active','start_time'=>now()->subHours(100),'end_time'=>now()->addHour()]);$log=AttendanceLog::create(['session_id'=>$session->id,'student_id'=>$s->id,'check_in_at'=>now()->subHours($hours),'check_out_at'=>now(),'status'=>'present','attendance_mark'=>'present','review_status'=>$review]);$log->forceFill(['academic_year_id'=>$period,'approved_hours'=>$hours])->save();return $log;}
 private function rebuild(Student $s,int $p=1):void{DB::transaction(fn()=>app(SemesterTraining::class)->rebuild(Student::whereKey($s->id)->lockForUpdate()->first(),$p));}
 public function test_boundaries_and_cap():void{foreach([0,53.99] as $h)$this->assertFalse(SemesterTraining::eligible($h));foreach([54,89.99,90] as $h)$this->assertTrue(SemesterTraining::eligible($h));$this->assertFalse(SemesterTraining::eligible(90.01));$this->assertEquals(90,SemesterTraining::capped(120));}
 public function test_cap_preserves_duration_and_corrections():void{$s=$this->student();$a=$this->log($s,88);$b=$this->log($s,5);$this->rebuild($s);$this->assertEquals(90,$s->fresh()->completed_training_hours);$this->assertTrue($s->fresh()->is_eligible_for_completion);$this->assertEquals(2,$b->fresh()->credited_hours);$this->assertEquals(5,$b->fresh()->approved_hours);$this->assertNotNull($b->fresh()->check_out_at);$a->forceFill(['approved_hours'=>80])->save();$this->rebuild($s);$this->assertEquals(85,$s->fresh()->completed_training_hours);$this->assertEquals(5,$b->fresh()->credited_hours);$this->rebuild($s);$this->assertEquals(85,$s->fresh()->completed_training_hours);}
 public function test_semesters_are_independent():void{$s=$this->student();$p=AcademicYear::create(['academic_year'=>'2026-2027','semester'=>'2nd','start_date'=>'2027-01-01','end_date'=>'2027-05-31','is_active'=>true]);$this->log($s,60);$this->rebuild($s);$this->log($s,70,$p->id);$this->rebuild($s,$p->id);$this->assertEquals(60,$s->fresh()->completed_training_hours);app(SemesterTraining::class)->activate($p->id);$this->assertEquals(70,$s->fresh()->completed_training_hours);$this->log($s,40);$this->rebuild($s);$this->assertEquals(70,$s->fresh()->completed_training_hours);$this->assertEquals(90,DB::table('student_semester_hours')->where('student_id',$s->id)->where('academic_year_id',1)->value('credited_hours'));}
 public function test_unapproved_and_incomplete_logs_do_not_credit():void{$s=$this->student();$this->log($s,8,1,'pending');$this->log($s,8,1,'rejected');$a=$this->log($s,8);$a->session->update(['status'=>'cancelled']);$b=$this->log($s,8);$b->update(['check_out_at'=>null]);$this->rebuild($s);$this->assertEquals(0,$s->fresh()->completed_training_hours);$this->assertFalse($s->fresh()->is_eligible_for_completion);}
 public function test_ledger_replay_is_idempotent():void{$s=$this->student();$this->log($s,88);$log=$this->log($s,5);DB::transaction(fn()=>app(AttendanceLedger::class)->credit($log,$log->session,$s));$this->assertEquals(90,$s->fresh()->completed_training_hours);$this->assertEquals(5,$log->fresh()->approved_hours);$this->assertEquals(2,$log->fresh()->credited_hours);DB::transaction(fn()=>app(AttendanceLedger::class)->credit($log->fresh(),$log->session,$s->fresh()));$this->assertEquals(90,$s->fresh()->completed_training_hours);}
 public function test_student_is_forbidden_from_settings():void{$s=$this->student();Sanctum::actingAs($s->user);$this->getJson('/api/admin/training-semesters')->assertForbidden();}
 public function test_legacy_assignment_is_capped_and_audited():void{$s=$this->student();DB::table('student_training_legacy')->insert(['student_id'=>$s->id,'original_hours'=>100,'unassigned_hours'=>100,'original_snapshot'=>'{}']);app(SemesterTraining::class)->assignLegacy($s,1,95,'Reviewed signed records',$s->user_id);$this->assertEquals(90,$s->fresh()->completed_training_hours);$this->assertEquals(5,DB::table('student_training_legacy')->where('student_id',$s->id)->value('unassigned_hours'));$this->assertEquals(100,DB::table('student_training_legacy')->where('student_id',$s->id)->value('original_hours'));$this->assertEquals(1,DB::table('audit_events')->where('event','training.legacy_assigned')->count());}
 public function test_direct_eligibility_cannot_override_minimum():void{$s=$this->student();$s->forceFill(['completed_training_hours'=>10,'training_academic_year_id'=>1,'is_eligible_for_completion'=>true,'total_training_hours'=>10])->save();$this->assertFalse($s->fresh()->is_eligible_for_completion);$this->assertEquals(90,$s->fresh()->total_training_hours);}

 public function test_admin_can_create_and_select_semester():void{$s=$this->student();$u=$s->user;$u->update(['role'=>'admin']);Sanctum::actingAs($u);$this->getJson('/api/admin/training-semesters')->assertOk()->assertJsonPath('data.minimum',54);$p=$this->postJson('/api/admin/academic-years',['academic_year'=>'2026-2027','semester'=>'2nd','start_date'=>'2027-01-01','end_date'=>'2027-05-31','is_active'=>true])->assertCreated()->json('data.id');$this->putJson('/api/admin/academic-years/'.$p,['is_current'=>true])->assertOk();$this->assertEquals($p,$s->fresh()->training_academic_year_id);$this->assertEquals(1,AcademicYear::where('is_current',true)->count());}
 public function test_missing_semester_cannot_silently_merge_hours():void{$s=$this->student();$l=$this->log($s,2);$l->session->update(['start_time'=>now()->addYears(5)]);try{app(SemesterTraining::class)->periodFor($l->session->fresh());$this->fail('Expected semester validation');}catch(\Illuminate\Validation\ValidationException $e){$this->assertArrayHasKey('semester',$e->errors());}}
 public function test_migration_preserves_unknown_historical_balance():void{$s=$this->student();Schema::drop('student_semester_hours');Schema::drop('student_training_legacy');Schema::drop('training_period_guard');Schema::table('students',function(Blueprint $t){$t->dropIndex('students_training_academic_year_id_index');$t->dropColumn('training_academic_year_id');});Schema::table('attendance_logs',function(Blueprint $t){$t->dropIndex('attendance_logs_academic_year_id_index');$t->dropColumn(['academic_year_id','approved_hours']);});DB::table('students')->where('id',$s->id)->update(['completed_training_hours'=>110]);(require database_path('migrations/2026_11_26_000003_add_semester_training_balances.php'))->up();$this->assertEquals(110,DB::table('student_training_legacy')->where('student_id',$s->id)->value('unassigned_hours'));$this->assertEquals(0,$s->fresh()->completed_training_hours);$snapshot=json_decode(DB::table('student_training_legacy')->where('student_id',$s->id)->value('original_snapshot'),true);$this->assertEquals(110,$snapshot['completed_training_hours']);}

 public function test_completion_certificate_requires_current_eligible_balance():void{$s=$this->student();$method=new \ReflectionMethod(\App\Http\Controllers\API\Web\Admin\CertificateController::class,'checkEligibility');$controller=app(\App\Http\Controllers\API\Web\Admin\CertificateController::class);try{$method->invoke($controller,$s,'completion');$this->fail('Under 54 must be rejected');}catch(\Illuminate\Validation\ValidationException $e){$this->assertArrayHasKey('student_ids',$e->errors());}$this->log($s,54);$this->rebuild($s);$method->invoke($controller,$s->fresh(),'completion');$this->assertTrue($s->fresh()->is_eligible_for_completion);}
}
